//! Core Adobe UCS2 CMaps embedded for mobile/offline PDF extraction.

use base64::{engine::general_purpose::STANDARD, Engine as _};
use std::sync::OnceLock;

const CNS_B64: &str = concat!(
    "",
    "",
    "",
    "",
    "",
    "",
    "",
);
static CNS_BYTES: OnceLock<Vec<u8>> = OnceLock::new();

const GB_B64: &str = concat!(
    "",
    "",
    "",
    "",
    "",
    "",
);
static GB_BYTES: OnceLock<Vec<u8>> = OnceLock::new();

const JAPAN_B64: &str = concat!(
    "",
    "",
    "",
    "",
    "",
    "",
    "",
);
static JAPAN_BYTES: OnceLock<Vec<u8>> = OnceLock::new();

const KOREA_B64: &str = concat!(
    "",
    "",
    "",
    "",
);
static KOREA_BYTES: OnceLock<Vec<u8>> = OnceLock::new();

fn decoded(cell: &'static OnceLock<Vec<u8>>, encoded: &str) -> &'static [u8] {
    cell.get_or_init(|| STANDARD.decode(encoded).expect("checked-in CMap base64 is valid"))
        .as_slice()
}

pub(crate) fn get(name: &str) -> Option<&'static [u8]> {
    match name {
        "Adobe-CNS1-UCS2.bcmap" => Some(decoded(&CNS_BYTES, CNS_B64)),
        "Adobe-GB1-UCS2.bcmap" => Some(decoded(&GB_BYTES, GB_B64)),
        "Adobe-Japan1-UCS2.bcmap" => Some(decoded(&JAPAN_BYTES, JAPAN_B64)),
        "Adobe-Korea1-UCS2.bcmap" => Some(decoded(&KOREA_BYTES, KOREA_B64)),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn all_mobile_cmaps_decode() {
        for name in [
            "Adobe-CNS1-UCS2.bcmap",
            "Adobe-GB1-UCS2.bcmap",
            "Adobe-Japan1-UCS2.bcmap",
            "Adobe-Korea1-UCS2.bcmap",
        ] {
            assert!(get(name).is_some_and(|bytes| bytes.len() > 20_000));
        }
    }
}

